<?php
namespace App\Http\Controllers;
use App\Models\Quote; use Illuminate\Http\Request;
class QuoteController extends Controller { public function index(Request $request){$term=trim((string)$request->query('q'));$quotes=Quote::query()->with('user:id,name')->search($term)->latest()->paginate(12)->withQueryString();return view('quotes.index',compact('quotes','term'));} public function store(Request $request){$data=$request->validate(['content'=>['required','string','min:3','max:155']]);$request->user()->quotes()->create($data);return back()->with('success','تم نشر اقتباسك بنجاح.');} public function edit(Quote $quote){$this->authorize('update',$quote);return view('quotes.edit',compact('quote'));} public function update(Request $request,Quote $quote){$this->authorize('update',$quote);$data=$request->validate(['content'=>['required','string','min:3','max:155']]);$quote->update($data);return redirect()->route('quotes.index')->with('success','تم تحديث اقتباسك بنجاح.');} public function destroy(Quote $quote){$this->authorize('delete',$quote);$quote->delete();return back()->with('success','تم حذف اقتباسك بنجاح.');} }
